// WF-01 | Stage 6 - Voice AI Dialogue Generator (Gemini 3.8 Flash)
const req = $("02 Validation & Phone Format").first().json;
const lead = $("04 Fetch Lead Context").first()?.json || {};
const runRecord = $("05 Create Workflow Run").first().json;

const customerName = (lead.first_name && lead.first_name !== "Quý khách")
  ? (lead.first_name + " " + (lead.last_name || "")).trim()
  : (req.full_name || "Quý khách");
const company = lead.company_name || "doanh nghiệp của mình";

let script = {
  greeting: "Dạ em chào anh/chị " + customerName + ", em gọi từ hệ thống AI Sales Agent.",
  hook: "Em thấy bên " + company + " đang quan tâm giải pháp tự động hóa bán hàng và tổng đài AI.",
  pitch: "Hiện bên em có gói Starter (2 triệu/tháng), gói Pro (5 triệu/tháng) và Enterprise tích hợp Voice AI, RAG pgvector và tự động chốt báo giá 24/7.",
  cta: "Anh/chị đang quan tâm gói nào hoặc cần em tư vấn chi tiết phần nào ạ?"
};
let llmModelUsed = "rule-fallback";

let geminiKey = "";
let geminiModel = "gemini-3.8-flash";
try {
  geminiKey = $env.GEMINI_API_KEY || "";
  geminiModel = $env.GEMINI_MODEL || "gemini-3.8-flash";
} catch (e) {}

if (geminiKey) {
  try {
    const prompt = "Bạn là chuyên viên Telesales B2B chuyên nghiệp tại Việt Nam. Hãy tạo kịch bản lời chào gọi điện ngắn gọn (JSON) cho khách hàng tên: " + customerName + ", công ty: " + company + ", ghi chú: " + req.context_notes + ". Trả về đúng JSON gồm 4 trường: greeting, hook, pitch, cta (tiếng Việt tự nhiên, lịch sự).";
    const modelToUse = geminiModel || "gemini-3-flash-preview";
    const resp = await this.helpers.httpRequest({
      method: "POST",
      url: "https://generativelanguage.googleapis.com/v1beta/models/" + modelToUse + ":generateContent?key=" + geminiKey,
      headers: { "Content-Type": "application/json" },
      body: { contents: [{ parts: [{ text: typeof prompt !== "undefined" ? prompt : aiPrompt }] }] },
      json: true,
      timeout: 15000
    });
    const textOut = resp?.candidates?.[0]?.content?.parts?.[0]?.text || resp?.output_text || "";
    const jsonMatch = textOut.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.greeting && parsed.pitch) {
        script = {
          greeting: parsed.greeting,
          hook: parsed.hook || script.hook,
          pitch: parsed.pitch,
          cta: parsed.cta || script.cta
        };
        llmModelUsed = geminiModel;
      }
    }
  } catch (err) {
    llmModelUsed = "gemini-fallback";
  }
}

return [{
  json: {
    workflow_run_id: runRecord.id,
    correlation_id: req.correlation_id,
    organization_id: lead.organization_id || req.organization_id,
    lead_id: lead.id || req.lead_id,
    phone: req.phone,
    customer_name: customerName,
    company_name: company,
    customer_speech: req.customer_speech,
    dialogue_script: script,
    llm_model: llmModelUsed,
    voice_profile: { provider: "Zero-Shot Voice Clone / Neural TTS", voice_id: req.voice_id, voice_name: req.voice_name, speed: 1.0 }
  }
}];

// WF-01 | Stage 7 - TTS & Telephony Dispatch (Twilio / Audio Stream)
const item = $input.first().json;
const callSid = 'CA' + Math.random().toString(16).slice(2, 10) + Math.random().toString(16).slice(2, 10);

const twiml = `
<Response>
  <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.greeting}</Say>
  <Pause length="1"/>
  <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.hook}</Say>
  <Pause length="1"/>
  <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.pitch}</Say>
  <Gather input="speech" timeout="5" language="vi-VN">
    <Say voice="Polly.Aditi" language="vi-VN">${item.dialogue_script.cta}</Say>
  </Gather>
</Response>
`.trim();

return [{
  json: {
    ...item,
    telephony: {
      provider: 'Twilio Voice',
      call_sid: callSid,
      to: item.phone,
      from: '+842471099999',
      status: 'in-progress',
      twiml
    }
  }
}];

// WF-01 | Stage 8 - Real Call Outcome & Gemini 3.8 Flash Conversation Analysis
const item = $input.first().json;
const customerSpeech = (item.customer_speech || "").trim() || "Anh quan tâm gói Pro, báo giá chi tiết và gửi demo cho anh nhé.";

let intent = "request_proposal";
let sentiment = "positive";
let scoreBoost = 20;
let aiReply = "Dạ vâng ạ! Với nhu cầu của " + item.customer_name + " tại " + item.company_name + ", gói Pro (5.000.000đ/tháng) là phù hợp nhất vì bao gồm đầy đủ Tổng đài Voice AI, RAG pgvector và tự động đồng bộ CRM. Em xin phép tạo ngay báo giá gửi anh/chị duyệt nhé ạ!";

const lower = customerSpeech.toLowerCase();
if (/chưa có ngân sách|đắt|để sau|tháng sau|bận/i.test(lower)) {
  intent = "budget_constraint";
  sentiment = "neutral";
  scoreBoost = 5;
  aiReply = "Dạ em hoàn toàn hiểu ạ. Bên em cũng có gói Starter tiết kiệm chỉ 2.000.000đ/tháng hoặc bản dùng thử miễn phí 14 ngày. Em xin phép gửi thông tin qua Email để anh/chị tham khảo trước nhé ạ!";
} else if (/không có nhu cầu|đừng gọi|không quan tâm|từ chối/i.test(lower)) {
  intent = "not_interested";
  sentiment = "negative";
  scoreBoost = -10;
  aiReply = "Dạ em cảm ơn anh/chị " + item.customer_name + " đã dành thời gian nghe máy. Khi nào bên mình cần giải pháp tự động hóa Sale thì liên hệ bên em nhé. Chúc anh/chị một ngày tốt lành ạ!";
} else if (/demo|hẹn|lịch|gặp|tư vấn trực tiếp/i.test(lower)) {
  intent = "schedule_meeting";
  sentiment = "positive";
  scoreBoost = 25;
  aiReply = "Dạ tuyệt vời ạ! Em xin phép đặt lịch họp Google Meet demo trực tiếp hệ thống cho " + item.customer_name + " vào 9h00 sáng mai và gửi lời mời qua Email của mình ngay bây giờ ạ!";
}

let geminiKey = "";
let geminiModel = "gemini-3.8-flash";
try {
  geminiKey = $env.GEMINI_API_KEY || "";
  geminiModel = $env.GEMINI_MODEL || "gemini-3.8-flash";
} catch (e) {}

if (geminiKey) {
  try {
    const prompt = "Bạn là AI Sales Agent đang gọi điện tư vấn cho khách hàng " + item.customer_name + " (" + item.company_name + ").\n" +
      "AI vừa chào: " + item.dialogue_script.greeting + " " + item.dialogue_script.pitch + "\n" +
      "Khách hàng vừa nói: \"" + customerSpeech + "\"\n" +
      "Hãy phân tích phản hồi của khách và trả lời tự nhiên bằng tiếng Việt (tối đa 3 câu). Trả về đúng định dạng JSON:\n" +
      "{\"intent\": \"request_proposal|schedule_meeting|pricing|budget_constraint|not_interested|general_inquiry\", \"sentiment\": \"positive|neutral|negative\", \"score_boost\": 20, \"ai_reply\": \"Câu trả lời của AI đọc cho khách nghe\"}";
    const modelToUse = geminiModel || "gemini-3-flash-preview";
    const resp = await this.helpers.httpRequest({
      method: "POST",
      url: "https://generativelanguage.googleapis.com/v1beta/models/" + modelToUse + ":generateContent?key=" + geminiKey,
      headers: { "Content-Type": "application/json" },
      body: { contents: [{ parts: [{ text: typeof prompt !== "undefined" ? prompt : aiPrompt }] }] },
      json: true,
      timeout: 15000
    });
    const textOut = resp?.candidates?.[0]?.content?.parts?.[0]?.text || resp?.output_text || "";
    const jsonMatch = textOut.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.ai_reply) aiReply = parsed.ai_reply;
      if (parsed.intent) intent = parsed.intent;
      if (["positive", "neutral", "negative"].includes(parsed.sentiment)) sentiment = parsed.sentiment;
      if (typeof parsed.score_boost === "number") scoreBoost = parsed.score_boost;
    }
  } catch (err) {}
}

const fullTranscript =
  "[00:02] AI (" + item.voice_profile.voice_name + "): " + item.dialogue_script.greeting + " " + item.dialogue_script.hook + "\n" +
  "[00:10] AI (" + item.voice_profile.voice_name + "): " + item.dialogue_script.pitch + " " + item.dialogue_script.cta + "\n" +
  "[00:19] Khách hàng (" + item.customer_name + "): \"" + customerSpeech + "\"\n" +
  "[00:25] AI (" + item.voice_profile.voice_name + "): " + aiReply;

return [{
  json: {
    ...item,
    call_result: {
      call_sid: item.telephony.call_sid,
      call_status: "completed",
      duration_seconds: 34,
      intent,
      sentiment,
      score_boost: scoreBoost,
      customer_speech: customerSpeech,
      ai_reply: aiReply,
      spoken_text: item.dialogue_script.greeting + " " + item.dialogue_script.pitch + " " + aiReply,
      transcript: fullTranscript,
      summary: "Cuộc gọi AI (" + sentiment + " / " + intent + "). Khách nói: \"" + customerSpeech + "\""
    }
  }
}];

