VALUES (COALESCE((SELECT id FROM organizations WHERE id = $1::uuid), (SELECT id FROM organizations LIMIT 1)), (SELECT id FROM leads WHERE id = $2::uuid LIMIT 1), 'voice', 'outbound', 'sales_call', $3::text, $4::text, NOW(), $5::jsonb)
