VALUES (COALESCE((SELECT id FROM organizations WHERE id = $1::uuid), (SELECT id FROM organizations LIMIT 1)), 'voice.outbound.completed', 'lead', (SELECT id FROM leads WHERE id = $2::uuid LIMIT 1), $3::uuid, $4::jsonb, 'pending')
RETURNING id;

