// WF-01 | Stage 13 - Success Log
const analysis = $("08 Call Analysis & Transcript").first().json;
const leadUpdate = $("10 Update Lead State").first().json;
const interactionRow = $("09 Save Interaction").first().json;

return [{
  json: {
    status: "success",
    data: {
      lead_id: analysis.lead_id,
      interaction_id: interactionRow.id,
      customer_name: analysis.customer_name,
      company_name: analysis.company_name,
      phone: analysis.phone,
      llm_model: analysis.llm_model,
      voice_profile: analysis.voice_profile,
      dialogue_script: analysis.dialogue_script,
      call_result: analysis.call_result,
      updated_lead: leadUpdate,
      workflow_run_id: analysis.workflow_run_id,
      correlation_id: analysis.correlation_id
    }
  }
}];

// WF-01 | Stage 16 - Error Handle
const err = $input.first().json?.execution?.error || {};
const failedNode = $input.first().json?.execution?.lastNodeExecuted || 'unknown';

let workflowRunId = null;
try { workflowRunId = $('05 Create Workflow Run').first()?.json?.id || null; } catch (e) {}

return [{
  json: {
    workflowRunId,
    error: { message: err.message || 'Call execution failed', failedNode, timestamp: new Date().toISOString() }
  }
}];
